# Generated by scripts/gen-data.py from the fork-linux argparse parser; do not edit.

_fork_linux_words() {
	local word
	while IFS= read -r word; do
		COMPREPLY+=("$word")
	done < <(compgen -W "$1" -- "$cur")
}

_fork_linux_files() {
	local word
	while IFS= read -r word; do
		COMPREPLY+=("$word")
	done < <(compgen -f -- "$cur")
}

_fork_linux_dirs() {
	local word
	while IFS= read -r word; do
		COMPREPLY+=("$word")
	done < <(compgen -d -- "$cur")
}

