_fork_linux_takes_value() {
	local option
	for option in $_fl_vopts; do
		[[ "$option" == "$1" ]] && return 0
	done
	return 1
}

_fork_linux() {
	local cur prev key="" word i skip=0 _fl_opts _fl_vopts _fl_subs _fl_pos _fl_pos_words
	COMPREPLY=()
	cur="${COMP_WORDS[COMP_CWORD]}"
	prev=""
	if ((COMP_CWORD > 0)); then
		prev="${COMP_WORDS[COMP_CWORD - 1]}"
	fi
	_fork_linux_node ""
	for ((i = 1; i < COMP_CWORD; i++)); do
		word="${COMP_WORDS[i]}"
		if ((skip)); then
			skip=0
			continue
		fi
		case "$word" in
			--)
				_fork_linux_files
				return 0
				;;
			-*)
				if [[ "$word" != *=* ]] && _fork_linux_takes_value "$word"; then
					skip=1
				fi
				continue
				;;
		esac
		if [[ -n "$_fl_subs" ]]; then
			key="${key:+$key }$word"
			_fork_linux_node "$key"
		fi
	done
	if ((skip)); then
		_fork_linux_value "$key" "$prev"
		return 0
	fi
	if [[ "$cur" == -* ]]; then
		_fork_linux_words "$_fl_opts"
	elif [[ -n "$_fl_subs" ]]; then
		_fork_linux_words "$_fl_subs"
	elif [[ -n "$_fl_pos_words" ]]; then
		_fork_linux_words "$_fl_pos_words"
	elif ((_fl_pos)); then
		_fork_linux_files
	fi
	return 0
}

_fork_linux_fork() {
	local cur prev
	COMPREPLY=()
	cur="${COMP_WORDS[COMP_CWORD]}"
	prev=""
	if ((COMP_CWORD > 0)); then
		prev="${COMP_WORDS[COMP_CWORD - 1]}"
	fi
	if [[ "$prev" == "--prefix" ]]; then
		_fork_linux_dirs
	elif [[ "$cur" == -* ]]; then
		_fork_linux_words '-h --help -V --version --prefix --gui --no-gui --offline -v --verbose -q --quiet --allow-root'
	else
		if ((COMP_CWORD == 1)); then
			_fork_linux_words 'open'
		fi
		_fork_linux_files
	fi
	return 0
}

complete -o filenames -F _fork_linux fork-linux
complete -o filenames -F _fork_linux_fork fork
